 44	func validatePublicURL(ctx context.Context, raw string) (*url.URL, error) {
 45		u, err := url.Parse(raw)
 46		if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" || u.User != nil {
 47			return nil, fmt.Errorf("invalid endpoint")
 48		}
 49		ips, err := net.DefaultResolver.LookupIP(ctx, "ip", u.Hostname())
 50		if err != nil || len(ips) == 0 {
 51			return nil, fmt.Errorf("unresolvable endpoint")
 52		}
 53		for _, ip := range ips {
 54			if !publicIP(ip) {
 55				return nil, fmt.Errorf("private endpoint")
 56			}
 57		}
 58		return u, nil
 59	}
