 61	func integrationHTTPClient() *http.Client {
 62		dialer := &net.Dialer{Timeout: 3 * time.Second}
 63		transport := &http.Transport{Proxy: nil, DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
 64			host, port, err := net.SplitHostPort(addr)
 65			if err != nil {
 66				return nil, err
 67			}
 68			ips, err := net.DefaultResolver.LookupIP(ctx, "ip", host)
 69			if err != nil || len(ips) == 0 {
 70				return nil, fmt.Errorf("unresolvable endpoint")
 71			}
 72			for _, ip := range ips {
 73				if !publicIP(ip) {
 74					return nil, fmt.Errorf("private endpoint")
 75				}
 76			}
 77			return dialer.DialContext(ctx, network, net.JoinHostPort(ips[0].String(), port))
 78		}}
 79		client := &http.Client{Timeout: 3 * time.Second, Transport: transport}
 80		client.CheckRedirect = func(req *http.Request, via []*http.Request) error {
 81			if len(via) >= 10 {
 82				return fmt.Errorf("too many redirects")
 83			}
 84			_, err := validatePublicURL(req.Context(), req.URL.String())
 85			return err
 86		}
 87		return client
 88	}
